INSERT INTO "public"."tbl_data_chat_message" ("id", "session_id", "role", "content", "message_type", "metadata", "create_time") VALUES (3769, '93e56f1b-514d-4d8b-a74f-a359b17072ed', 'assistant', '
    <div class="agent-response-block" style="display: block !important; width: 100% !important;">
      <div class="agent-response-title">执行SQL</div>
